import { Vector2Like } from "../Abstract/Vectors/Vector2Like";
export class Square {
    center;
    sideLength;
    static Create(center = Vector2Like.Create(), sideLength = 1) {
        return new Square(center, sideLength);
    }
    constructor(center = Vector2Like.Create(), sideLength = 1) {
        this.center = center;
        this.sideLength = sideLength;
    }
}
